function drawVinylPickup(ctx, x, y, r, color, spin) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(spin * 0.0174533); // deg to rad
  // vinyl disc
  ctx.fillStyle = color;
  ctx.strokeStyle = '#111';
  ctx.lineWidth = r*0.08;
  ctx.beginPath(); ctx.arc(0, 0, r, 0, Math.PI*2); ctx.fill(); ctx.stroke();
  // grooves
  ctx.strokeStyle = '#222';
  ctx.lineWidth = r*0.04;
  for(let i=1;i<5;i++){
    ctx.beginPath(); ctx.arc(0, 0, r*0.4 + i*r*0.12, 0, Math.PI*2); ctx.stroke();
  }
  // center label
  ctx.fillStyle = '#eee';
  ctx.beginPath(); ctx.arc(0, 0, r*0.18, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = '#c33';
  ctx.font = `${r*0.22}px sans-serif`;
  ctx.textAlign = 'center'; ctx.textBaseline = 'middle';
  ctx.fillText('●', 0, 0);
  // tone arm / pickup
  ctx.rotate(-spin*0.6 - 0.8); // counter-spin + offset
  ctx.strokeStyle = '#555';
  ctx.lineWidth = r*0.09;
  ctx.beginPath();
  ctx.moveTo(r*0.9, -r*0.6);
  ctx.quadraticCurveTo(r*1.8, -r*1.1, r*2.2, -r*0.4);
  ctx.stroke();
  ctx.fillStyle = '#f44';
  ctx.beginPath(); ctx.arc(r*2.2, -r*0.4, r*0.14, 0, Math.PI*2); ctx.fill();
  ctx.restore();
  // highlight glare
  ctx.save();
  ctx.translate(x - r*0.3, y - r*0.3);
  ctx.rotate(0.6);
  ctx.fillStyle = 'rgba(255,255,255,0.35)';
  ctx.beginPath(); ctx.ellipse(0, 0, r*0.7, r*0.2, 0, 0, Math.PI*2); ctx.fill();
  ctx.restore();
}

